      sequenceName.hashCode ^
      timestamp.hashCode ^
      completedExposures.hashCode ^
      completedIntegrationSecs.hashCode ^
      canResume.hashCode ^
      ageSeconds.hashCode;

  @override
  bool operator ==(Object other) =>
